import React from 'react';
import './Services.css';

const Services = () => {
  const services = [
    {
      title: "DESIGN & ENGINEERING",
      description: "Structural analysis, load calculations, and custom design solutions."
    },
    {
      title: "MANUFACTURING",
      description: "Precision fabrication using German engineering standards and quality materials."
    },
    {
      title: "INSTALLATION",
      description: "Professional on-site assembly and installation by certified technicians."
    },
    {
      title: "MAINTENANCE",
      description: "Ongoing support, inspections, and maintenance services for all structures."
    }
  ];

  return (
    <section className="services section" id="services">
      <div className="container">
        <h2 className="section-title">SERVICES</h2>

        <div className="services-list">
          {services.map((service, index) => (
            <div key={index} className="service-item">
              <div className="service-content">
                <h3>{service.title}</h3>
                <p>{service.description}</p>
              </div>
              <div className="service-number">{String(index + 1).padStart(2, '0')}</div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Services;
